import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry triu_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<8>;
    .reg .s32  %r<20>;
    .reg .s64  %rd<20>;
    .reg .f32  %f<8>;

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [N];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    // row = blockIdx.y * blockDim.y + threadIdx.y
    mov.u32 %r2, %ctaid.y;
    mov.u32 %r3, %ntid.y;
    mov.u32 %r4, %tid.y;
    mad.lo.s32 %r5, %r2, %r3, %r4;   // row

    // col = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r6, %ctaid.x;
    mov.u32 %r7, %ntid.x;
    mov.u32 %r8, %tid.x;
    mad.lo.s32 %r9, %r6, %r7, %r8;   // col

    // bounds check
    setp.ge.s32 %p1, %r5, %r1;
    setp.ge.s32 %p2, %r9, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    // accumulator
    mov.f32 %f1, 0f00000000;
    mov.u32 %r10, 0;   // k

LOOP_START:
    setp.ge.s32 %p4, %r10, %r1;
    @%p4 bra LOOP_END;

    // A index = row * N + k
    mad.lo.s32 %r11, %r5, %r1, %r10;
    mul.wide.s32 %rd4, %r11, 4;
    add.s64 %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];

    // B index = k * N + col
    mad.lo.s32 %r12, %r10, %r1, %r9;
    mul.wide.s32 %rd6, %r12, 4;
    add.s64 %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r10, %r10, 1;
    bra LOOP_START;

LOOP_END:
    // C index = row * N + col
    mad.lo.s32 %r13, %r5, %r1, %r9;
    mul.wide.s32 %rd8, %r13, 4;
    add.s64 %rd9, %rd3, %rd8;

    setp.lt.s32 %p5, %r9, %r5;   // col < row -> zero out
    @%p5 bra STORE_ZERO;

    st.global.f32 [%rd9], %f1;
    bra DONE;

STORE_ZERO:
    mov.f32 %f4, 0f00000000;
    st.global.f32 [%rd9], %f4;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul")

class ModelNew(nn.Module):
    """
    Model that performs matrix multiplication (C = A * B) for upper triangular matrices
    using a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        assert A.shape == B.shape
        assert A.dim() == 2 and A.shape[0] == A.shape[1]
        N = A.shape[0]

        A = A.contiguous()
        B = B.contiguous()

        C = torch.empty((N, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 16, 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y

        module.launch(
            "triu_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

